//! Content-blind DTOs for the Companion Relay wire contract.
//!
//! Bearer capabilities are generated by clients, sent only in authorization
//! headers, and retained only by the authorized endpoint. Creation requests
//! carry lowercase SHA-256 verifiers, never the capabilities themselves.
//!
//! Exact routes and bodies:
//!
//! - `POST /v1/companion/pairing-sessions`: [`PairingSessionCreate`] ->
//!   [`PairingSessionCreated`].
//! - `POST /v1/companion/pairing-sessions/:id/respond`: raw
//!   `application/octet-stream` -> [`PairingResponseAccepted`].
//! - `GET /v1/companion/pairing-sessions/:id`: read bearer -> pending `204`
//!   or raw `application/octet-stream`.
//! - `DELETE /v1/companion/pairing-sessions/:id`: cancel bearer -> `204`.
//! - `POST /v1/companion/mailboxes`: [`MailboxCreate`] -> [`MailboxCreated`].
//! - `POST /v1/companion/mailboxes/:id/envelopes`: write bearer and direct
//!   [`OpaqueEnvelope`] JSON -> [`EnvelopeAccepted`].
//! - `GET /v1/companion/mailboxes/:id/envelopes?cursor=N&limit=N`: read bearer
//!   -> [`MailboxPage`] or `409` [`MailboxResetRequired`].
//! - `GET /v1/companion/mailboxes/:id/live?cursor=N`: read bearer -> SSE with
//!   direct envelope JSON in `envelope` events plus `reconcile`/`revoked`.
//! - `POST /v1/companion/mailboxes/:id/ack`: ack bearer and [`MailboxAck`] ->
//!   [`MailboxAcknowledged`].
//! - `DELETE /v1/companion/mailboxes/:id`: revoke bearer ->
//!   [`MailboxRevoked`].
//! - `POST /v1/companion/push/register`: push bearer and [`PushRegister`].
//! - `DELETE /v1/companion/push/register/:device_id`: push bearer and
//!   [`PushUnregister`].

use crate::crypto::{decode_array, sha256};
use crate::envelope::OpaqueEnvelope;
use crate::{parse_timestamp, require, validate_identifier, validate_text, Result};
use serde::{Deserialize, Serialize};

pub const MAX_PAIRING_RESPONSE_BYTES: usize = 64 * 1024;
pub const MAX_PAGE_ENVELOPES: usize = 256;
pub const MAX_SAFE_RELAY_INTEGER: u64 = (1_u64 << 53) - 1;
pub const PAIRING_SESSIONS_PATH: &str = "/v1/companion/pairing-sessions";
pub const MAILBOXES_PATH: &str = "/v1/companion/mailboxes";
pub const PUSH_REGISTRATION_PATH: &str = "/v1/companion/push/register";

fn validate_schema(actual: &str, expected: &str) -> Result<()> {
    require(
        actual == expected,
        format!("unsupported relay schema {actual}"),
    )
}

fn validate_verifier(label: &str, value: &str) -> Result<()> {
    require(
        value.len() == 64
            && value
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)),
        format!("{label} must be a lowercase SHA-256 verifier"),
    )
}

/// Verify and hash a 32-byte base64url bearer capability for a create DTO.
pub fn capability_verifier(capability: &str) -> Result<String> {
    let capability = validate_bearer_capability(capability)?;
    Ok(hex(&sha256(&capability)))
}

pub fn validate_bearer_capability(capability: &str) -> Result<[u8; 32]> {
    decode_array::<32>("relay bearer capability", capability)
}

pub fn validate_opaque_pairing_response(bytes: &[u8]) -> Result<()> {
    require(
        !bytes.is_empty() && bytes.len() <= MAX_PAIRING_RESPONSE_BYTES,
        "opaque pairing response must contain 1..=65536 bytes",
    )
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PairingSessionCreate {
    pub schema: String,
    pub expires_at: String,
    pub read_verifier: String,
    pub cancel_verifier: String,
}

impl PairingSessionCreate {
    pub fn validate(&self) -> Result<()> {
        validate_schema(&self.schema, "tohseno.companion-pairing-session-create/1")?;
        parse_timestamp(&self.expires_at)?;
        validate_verifier("pairing read verifier", &self.read_verifier)?;
        validate_verifier("pairing cancel verifier", &self.cancel_verifier)?;
        require(
            self.read_verifier != self.cancel_verifier,
            "pairing read and cancel capabilities must be distinct",
        )
    }
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PairingSessionCreated {
    pub schema: String,
    pub session_id: String,
    pub expires_at: String,
}

impl PairingSessionCreated {
    pub fn validate(&self) -> Result<()> {
        validate_schema(&self.schema, "tohseno.companion-pairing-session-created/1")?;
        validate_identifier("relay pairing session ID", &self.session_id)?;
        parse_timestamp(&self.expires_at).map(|_| ())
    }
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PairingResponseAccepted {
    pub schema: String,
    pub accepted: bool,
    pub duplicate: bool,
}

impl PairingResponseAccepted {
    pub fn validate(&self) -> Result<()> {
        validate_schema(
            &self.schema,
            "tohseno.companion-pairing-response-accepted/1",
        )?;
        require(self.accepted, "relay rejected the pairing response")
    }
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct MailboxCreate {
    pub schema: String,
    pub write_verifier: String,
    pub read_verifier: String,
    pub ack_verifier: String,
    pub revoke_verifier: String,
    pub push_verifier: String,
}

impl MailboxCreate {
    pub fn validate(&self) -> Result<()> {
        validate_schema(&self.schema, "tohseno.companion-mailbox-create/1")?;
        let verifiers = [
            ("mailbox write verifier", &self.write_verifier),
            ("mailbox read verifier", &self.read_verifier),
            ("mailbox acknowledgement verifier", &self.ack_verifier),
            ("mailbox revoke verifier", &self.revoke_verifier),
            ("mailbox push verifier", &self.push_verifier),
        ];
        for (label, verifier) in verifiers {
            validate_verifier(label, verifier)?;
        }
        let mut unique = [
            &self.write_verifier,
            &self.read_verifier,
            &self.ack_verifier,
            &self.revoke_verifier,
            &self.push_verifier,
        ];
        unique.sort();
        require(
            unique.windows(2).all(|pair| pair[0] != pair[1]),
            "mailbox endpoint capabilities must be distinct",
        )
    }
}

