#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct EnvelopeAccepted {
    pub schema: String,
    pub accepted: bool,
    pub duplicate: bool,
    pub cursor: u64,
}

impl EnvelopeAccepted {
    pub fn validate(&self) -> Result<()> {
        validate_schema(&self.schema, "tohseno.companion-envelope-accepted/1")?;
        require(self.accepted, "relay rejected the opaque envelope")?;
        require(
            (1..=MAX_SAFE_RELAY_INTEGER).contains(&self.cursor),
            "accepted envelope cursor must be a positive cross-language safe integer",
        )
    }
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CursorEnvelope {
    pub cursor: u64,
    pub envelope: OpaqueEnvelope,
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct MailboxPage {
    pub schema: String,
    pub envelopes: Vec<CursorEnvelope>,
    pub next_cursor: u64,
    pub head_cursor: u64,
    pub has_more: bool,
}

impl MailboxPage {
    pub fn validate_routing(&self, mailbox_id: &str, after_cursor: u64) -> Result<()> {
        validate_schema(&self.schema, "tohseno.companion-mailbox-page/1")?;
        validate_identifier("relay mailbox ID", mailbox_id)?;
        require(
            after_cursor <= MAX_SAFE_RELAY_INTEGER
                && self.next_cursor <= MAX_SAFE_RELAY_INTEGER
                && self.head_cursor <= MAX_SAFE_RELAY_INTEGER,
            "relay mailbox cursors exceed the cross-language safe integer range",
        )?;
        require(
            self.envelopes.len() <= MAX_PAGE_ENVELOPES,
            "relay mailbox page contains too many envelopes",
        )?;
        require(
            self.next_cursor >= after_cursor && self.head_cursor >= self.next_cursor,
            "relay mailbox cursors are inconsistent",
        )?;
        let mut previous = after_cursor;
        for entry in &self.envelopes {
            require(
                entry.cursor <= MAX_SAFE_RELAY_INTEGER,
                "relay mailbox entry cursor exceeds the cross-language safe integer range",
            )?;
            require(
                entry.cursor > previous && entry.cursor <= self.head_cursor,
                "relay mailbox entry cursors are not strictly increasing",
            )?;
            require(
                entry.envelope.header.mailbox_id == mailbox_id,
                "mailbox page contains a misrouted envelope",
            )?;
            entry.envelope.validate_relay_shape()?;
            previous = entry.cursor;
        }
        if let Some(last) = self.envelopes.last() {
            require(
                self.next_cursor == last.cursor,
                "next cursor does not match the final mailbox entry",
            )?;
        } else {
            require(
                self.next_cursor == after_cursor,
                "empty mailbox page advanced its cursor",
            )?;
        }
        require(
            self.has_more == (self.next_cursor < self.head_cursor),
            "mailbox has_more does not match its cursors",
        )
    }
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct MailboxResetRequired {
    pub schema: String,
    pub reset_required: bool,
    pub reset_before_cursor: u64,
    pub head_cursor: u64,
}

impl MailboxResetRequired {
    pub fn validate(&self) -> Result<()> {
        validate_schema(&self.schema, "tohseno.companion-mailbox-reset-required/1")?;
        require(
            self.reset_required,
            "mailbox reset response is inconsistent",
        )?;
        require(
            self.reset_before_cursor <= self.head_cursor,
            "mailbox reset cursor exceeds the head cursor",
        )?;
        require(
            self.head_cursor <= MAX_SAFE_RELAY_INTEGER,
            "mailbox reset cursors exceed the cross-language safe integer range",
        )
    }
}

