#[derive(Clone, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PushRegister {
    pub schema: String,
    pub mailbox_id: String,
    pub device_id: String,
    /// Opaque APNs token. It is secret diagnostic data and must never be logged.
    pub apns_token: String,
}

impl std::fmt::Debug for PushRegister {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("PushRegister")
            .field("schema", &self.schema)
            .field("mailbox_id", &"[REDACTED]")
            .field("device_id", &"[REDACTED]")
            .field("apns_token", &"[REDACTED]")
            .finish()
    }
}

impl PushRegister {
    pub fn validate(&self) -> Result<()> {
        validate_schema(&self.schema, "tohseno.companion-push-register/1")?;
        validate_identifier("push mailbox ID", &self.mailbox_id)?;
        validate_identifier("push device ID", &self.device_id)?;
        validate_text("opaque APNs token", &self.apns_token, 512)
    }
}

