#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RelayHealth {
    pub schema: String,
    pub service_version: String,
    pub ready: bool,
    pub push_enabled: bool,
    pub maximum_envelope_bytes: u64,
    pub retention_seconds: u64,
}

impl RelayHealth {
    pub fn validate(&self) -> Result<()> {
        validate_schema(&self.schema, "tohseno.companion-relay-health/1")?;
        validate_text("relay service version", &self.service_version, 64)?;
        require(
            self.maximum_envelope_bytes > 0 && self.retention_seconds > 0,
            "relay health limits must be positive",
        )
    }
}

fn hex(bytes: &[u8]) -> String {
    const DIGITS: &[u8; 16] = b"0123456789abcdef";
    let mut encoded = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        encoded.push(DIGITS[(byte >> 4) as usize] as char);
        encoded.push(DIGITS[(byte & 0x0f) as usize] as char);
    }
    encoded
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::crypto::base64url;

    fn capability(byte: u8) -> String {
        base64url(&[byte; 32])
    }

    #[test]
    fn verifier_is_lowercase_sha256_and_bearer_is_absent_from_json() {
        let read_capability = capability(1);
        let cancel_capability = capability(2);
        let request = PairingSessionCreate {
            schema: "tohseno.companion-pairing-session-create/1".into(),
            expires_at: "2026-08-15T12:02:00Z".into(),
            read_verifier: capability_verifier(&read_capability).unwrap(),
            cancel_verifier: capability_verifier(&cancel_capability).unwrap(),
        };
        request.validate().unwrap();
        let json = serde_json::to_string(&request).unwrap();
        assert!(!json.contains(&read_capability));
        assert!(!json.contains(&cancel_capability));
    }

    #[test]
    fn all_mailbox_endpoint_capabilities_must_be_distinct() {
        let verifier = capability_verifier(&capability(3)).unwrap();
        let request = MailboxCreate {
            schema: "tohseno.companion-mailbox-create/1".into(),
            write_verifier: verifier.clone(),
            read_verifier: verifier.clone(),
            ack_verifier: verifier.clone(),
            revoke_verifier: verifier.clone(),
            push_verifier: verifier,
        };
        assert!(request.validate().is_err());
    }

    #[test]
    fn raw_pairing_response_is_bounded_without_parsing() {
        validate_opaque_pairing_response(b"opaque ciphertext").unwrap();
        assert!(validate_opaque_pairing_response(&[]).is_err());
        assert!(
            validate_opaque_pairing_response(&vec![0; MAX_PAIRING_RESPONSE_BYTES + 1]).is_err()
        );
    }

    #[test]
    fn relay_cursors_reject_values_javascript_cannot_represent_exactly() {
        let accepted = EnvelopeAccepted {
            schema: "tohseno.companion-envelope-accepted/1".into(),
            accepted: true,
            duplicate: false,
            cursor: MAX_SAFE_RELAY_INTEGER + 1,
        };
        assert!(accepted.validate().is_err());
        let acknowledgement = MailboxAck {
            schema: "tohseno.companion-mailbox-ack/1".into(),
            cursor: MAX_SAFE_RELAY_INTEGER + 1,
        };
        assert!(acknowledgement.validate().is_err());
    }

    #[test]
    fn push_registration_debug_is_content_free() {
        let registration = PushRegister {
            schema: "tohseno.companion-push-register/1".into(),
            mailbox_id: "mailbox_private".into(),
            device_id: "device_private".into(),
            apns_token: "private-apns-token".into(),
        };
        let debug = format!("{registration:?}");
        assert!(!debug.contains("mailbox_private"));
        assert!(!debug.contains("device_private"));
        assert!(!debug.contains("private-apns-token"));
    }
}
